int32_t dk_param_set(uint32_t track, uint32_t word, int32_t raw);

/* Declare a machine of this module: `index` is its DK_MACHINE_ID_<ID> (build/gen/module_ids.h): the position of the id in the `[[machine]]` list of module.toml, which is the row of its key in the keys table. `name` the long name, `short_name` the short one. The DSP entry points are found by the names `_<id>_render` and `_<id>_note_on`. Returns the builder handle; on an error (full, bad index) a placeholder, and the error is reported when `init` returns. Context: init. Since runtime 0.7.0. */
dk_machine *dk_module_ctx_add_machine(dk_module_ctx *ctx, uint32_t index, const char *name, const char *short_name);

/* Add a page to the machine, after the pages already added: `name` is its title, `short_name` its tab label on a device that keeps knobs in page rows. Returns the page handle (a placeholder on an error). Context: init. Since runtime 0.7.0. */
dk_page *dk_machine_add_page(dk_machine *m, const char *name, const char *short_name);

/* Add a machine parameter on the next knob of the page (word = order of declaration, range 0 to 127 until `dk_param_range`), default value `def`. Returns the parameter handle (a placeholder on an error). Context: init. Since runtime 0.7.0. */
dk_param *dk_page_add_param(dk_page *p, const char *name, const char *short_name, uint32_t def);

/* Set the range of a machine parameter (default 0 to 127). Context: init. Since runtime 0.7.0. */
void dk_param_range(dk_param *prm, uint32_t min, uint32_t max);

/* Set the glyph of a machine parameter (DK_GLYPH_*); its range must fit the glyph, or the commit refuses the module. Context: init. Since runtime 0.7.0. */
void dk_param_glyph(dk_param *prm, uint32_t glyph);

/* Latch the parameter at note_on (machine contract 1.3). Context: init. Since runtime 0.7.0. */
void dk_param_latched(dk_param *prm);

/* Run `fn(arg, track)` when the parameter's knob is clicked on the machine's page. Context: init. Since runtime 0.7.0. */
void dk_param_on_click(dk_param *prm, dk_param_click_fn *fn, void *arg);

/* Make the page a native canvas page: `flags` are DK_PAGE_STOCK_OVERLAY or DK_PAGE_WIDE_CANVAS (or 0), `draw` and `event` run in the UI task with `arg`. Context: init. Since runtime 0.7.0. */
void dk_page_canvas(dk_page *p, uint32_t flags, dk_page_draw_fn *draw, dk_page_event_fn *event, void *arg);

/* On a canvas page, bind a shared parameter of the machine to the encoder `slot` (0 to 7). Context: init. Since runtime 0.7.0. */
void dk_page_bind(dk_page *p, dk_param *prm, uint32_t slot);

/* On a canvas page, bind the page's local control number `local` to the encoder `slot` (0 to 7); its turns arrive in the event callback. Context: init. Since runtime 0.7.0. */
void dk_page_bind_local(dk_page *p, uint32_t local, uint32_t slot);

/* ---- service fx ---- */

/* Declare an effect of this module: `index` is its DK_FX_ID_<ID>: the position of the id in the `[[fx]]` list of module.toml, which is the row of its id in the keys table. `name` the long name, `short_name` the short one. The DSP entry is `_<id>_process`. Returns the builder handle (a placeholder on an error, reported at commit). Context: init. Since runtime 0.7.0. */
dk_fx *dk_module_ctx_add_fx(dk_module_ctx *ctx, uint32_t index, const char *name, const char *short_name);

/* Add the effect's page: `name` is its title, `short_name` its tab label (3 characters at most). Returns the page handle (a placeholder on an error). Context: init. Since runtime 0.7.0. */
dk_page *dk_fx_add_page(dk_fx *fx, const char *name, const char *short_name);

/* Add an effect parameter on the next knob of the page. `kind` is DK_PERCENT or DK_BIPOLAR (the display); `min`, `max` and `def` are in the parameter's unit. Returns the parameter handle (a placeholder on an error). Context: init. Since runtime 0.7.0. */
dk_param *dk_page_add_fx_param(dk_page *p, const char *name, const char *short_name, uint32_t kind, float min, float max, float def);

/* Set the routes the effect may run on (DK_ROUTE_MASTER, DK_ROUTE_SEND, or both) and the default one. Context: init. Since runtime 0.7.0. */
void dk_fx_routes(dk_fx *fx, uint32_t allowed, uint32_t def);

/* Set the default of the effect's MIX knob, 0 to 127 (127 when this is not called). Context: init. Since runtime 0.7.0. */
void dk_fx_mix(dk_fx *fx, uint32_t def);

/* ---- service ui ---- */

/* A YES/NO dialog: `done(arg, yes)` runs after it closed. 0 when shown, a negative code when not (another dialog is open, out of memory). Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns -1. */
int32_t dk_ui_confirm(dk_ui *ui, const char *title, const char *text, dk_ui_confirm_fn *done, void *arg);

/* A short message on the main screen that goes away by itself. 0 when shown, a negative code when not. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns -1. */
int32_t dk_ui_toast(dk_ui *ui, const char *text);

/* Call `fn(arg)` about every `period_ms` in the UI task (period 0 removes the timer of the pair `fn`, `arg`). 0 when set or removed, a negative code when it cannot be (table full). Rules in <dk/platform/ui.h>. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns -1. */
int32_t dk_ui_tick(dk_ui *ui, dk_ui_tick_fn *fn, void *arg, uint32_t period_ms);

/* Open the UI service: `*out` is the handle, the result 0. Without core/ui the result is DK_E_MISSING and `*out` is untouched. Context: init. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_ui_open(dk_module_ctx *ctx, dk_ui **out);

/* Fill and show a menu on top of the current view; negative when it cannot be. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_ui_menu_open(dk_ui_menu *m);

/* Close a menu. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_close(dk_ui_menu *m);

/* Put the cursor of a menu or list on a row (clamped); call before dk_ui_menu_open to start on the current choice. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_select(dk_ui_menu *m, int32_t row);

/* Fill an open menu again. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_refresh(dk_ui_menu *m);

/* 1 when the menu is open. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns 0. */
int32_t dk_ui_menu_is_open(const dk_ui_menu *m);

/* Add a row of text without an action. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_add_text(dk_ui_menu *m, const char *text);

/* Add a row that runs `run(arg, value)` on YES. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_add_action(dk_ui_menu *m, const char *text, dk_ui_action_fn *run, void *arg, int32_t value);

/* Add a row that opens another menu. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_add_submenu(dk_ui_menu *m, const char *text, dk_ui_menu *sub);

/* Add an ON/OFF row. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_add_toggle(dk_ui_menu *m, const char *text, int32_t *value, dk_ui_action_fn *changed, void *arg);

/* Add a number row changed by the encoder. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_add_value(dk_ui_menu *m, const char *text, int32_t *value, int32_t min, int32_t max, dk_ui_action_fn *changed, void *arg);

/* Set the check mark of a list row. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that does nothing. */
void dk_ui_menu_check(dk_ui_menu *list, int32_t row, int32_t on);

/* 1 when the list row is checked. Context: ui. Since runtime 0.7.0. Needs core/ui: without it the import binds to a stub that returns 0. */
int32_t dk_ui_menu_checked(const dk_ui_menu *list, int32_t row);

/* ---- service input ---- */

/* Open the panel input service: `*out` is the handle, the result 0. Without core/input the result is DK_E_MISSING and `*out` is untouched. Context: init. Since runtime 0.7.0. Needs core/input: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_input_open(dk_module_ctx *ctx, dk_input **out);

/* Press or release a panel key. See <dk/platform/input.h>. Context: ui. Since runtime 0.7.0. Needs core/input: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_input_key(dk_input *inp, uint32_t code, uint32_t down);

/* Turn an encoder by `delta`. Context: ui. Since runtime 0.7.0. Needs core/input: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_input_turn(dk_input *inp, uint32_t encoder, int32_t delta);

/* ---- service usb_bulk ---- */

/* Open the USB bulk service: `*out` is the handle, the result 0. Without core/usb-bulk the result is DK_E_MISSING and `*out` is untouched. See <dk/platform/usb_bulk.h>. Context: init. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_open(dk_module_ctx *ctx, dk_usb_bulk **out);

/* Add the vendor bulk interface (interface 2, EP2 OUT and IN, 512-byte packets) to the USB MIDI configuration, as usb_bulk_enable did. `io_id` is the I/O job that the service wakes when a receive buffer is full. Call it until it returns 0. Another job gets DK_E_BUSY (one owner). Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_enable(dk_usb_bulk *ub, int32_t io_id);

/* The job that called dk_usb_bulk_enable goes away (call it in fini): the service stops waking it and another job may enable the interface. 0, or DK_E_STATE for another job. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_disable(dk_usb_bulk *ub, int32_t io_id);

/* The next full receive buffer, in arrival order: 1 and `*buf`, `*len` set (the buffer is yours until dk_usb_bulk_release), or 0 when none is full. Never blocks. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_take(dk_usb_bulk *ub, void **buf, uint32_t *len);

/* Give a buffer from dk_usb_bulk_take back: it is queued for the next transfer. 0, or DK_E_STATE for a pointer that is not a taken buffer. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_release(dk_usb_bulk *ub, void *buf);

/* Send `len` bytes (1 to 16384) to the host on EP2 IN. The bytes are copied. 0, DK_E_BUSY when both send slots are in flight (the job is woken when one completes), DK_E_AGAIN when nothing is in flight and the engine refused, or another status. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_send(dk_usb_bulk *ub, const void *buf, uint32_t len);

/* State word: bit 0 enabled, bit 1 connected (the host configured interface 2), bit 2 wrong mode (the active USB port has no bulk route: not USB MIDI mode, and not USB AUDIO/MIDI with core/usb-bulk-audio; read live), bit 3 never set (take-over removed), bit 6 out only (USB AUDIO/MIDI with core/usb-bulk-audio is the active port: bulk OUT only, dk_usb_bulk_send returns E_STATE; read live), bits 8..15 receive buffers full, bits 16..23 send slots in flight. 0 without core/usb-bulk. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns 0. */
uint32_t dk_usb_bulk_state(dk_usb_bulk *ub);

/* Removed: always returns DK_USB_BULK_E_STATE (the USB take-over no longer exists; the bulk OUT interface works in USB AUDIO/MIDI without it). Kept so that the import table does not change. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_takeover(dk_usb_bulk *ub);

/* Removed: always returns DK_USB_BULK_E_STATE (the USB take-over no longer exists). Kept so that the import table does not change. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_usb_bulk_giveback(dk_usb_bulk *ub);

/* The receive ring of the service. `set` 0 or 1 sets the run-time ring switch (bit 1 of the usb-fast switch mask; default 1: a ring of up to 60 slots of 16 KiB, queued to the controller by the interrupt while the job writes the card; 0: the old 8 slots); a negative `set` only reads. The switch is read when the buffers are allocated (the next take-over or enable) and at every queueing. Returns the result word read with the DK_USB_BULK_RING_* macros of <dk/platform/usb_bulk.h>: the switch in bit 0, bit 1 always set (the service has the ring) and, in bits 8..15, the receive window in frames of 64 KiB that the live buffers take before the controller NAKs (0: none live, or the old window of 2). 0 without core/usb-bulk or when the adapter has no ring: the old behaviour. Context: any. Since runtime 0.7.0. Needs core/usb-bulk: without it the import binds to a stub that returns 0. */
int32_t dk_usb_bulk_ring(dk_usb_bulk *ub, int32_t set);

/* ---- service dsp_link ---- */

/* Open the DSP link service: `*out` is the handle, the result 0. Without core/dsp-link the result is DK_E_MISSING and `*out` is untouched. Context: init. Since runtime 0.7.0. Needs core/dsp-link: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_dsp_link_open(dk_module_ctx *ctx, dk_dsp_link **out);

/* Set the one per-block callback of core/dsp-link (0: off): `void cb(const volatile u16 *rec)`, called every block in the block interrupt with the copy of the previous DSP reply record. Keep it short; clear it in fini. See <dk/platform/dsp_link.h>. Context: ui. Since runtime 0.7.0. Needs core/dsp-link: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_dsp_link_set_tick(dk_dsp_link *dl, uint8_t *cb);

/* ---- service sdhc_large ---- */

/* Open the large card command service: `*out` is the handle, the result 0. Without core/sdhc-large the result is DK_E_MISSING and `*out` is untouched; `dk_sdhc_large_ctl` then returns 0, so a caller can go on without it. Context: init. Since runtime 0.7.0. Needs core/sdhc-large: without it the import binds to a stub that returns DK_E_MISSING. */
int32_t dk_sdhc_large_open(dk_module_ctx *ctx, dk_sdhc_large **out);

/* core/sdhc-large: the firmware's eMMC block write and read run a transfer as one card command of up to 1022 blocks (511 KiB) instead of 64 KiB pieces when its buffer lies inside the range the runtime sets, is 16-byte aligned and its length is a multiple of 512, while the switch is on. Key 0 is the switch (val 0 off, 1 on, another value changes nothing; returns the old value; RAM only, 1 at every boot). Key 1 reads a counter (val 0 calls of the firmware's block write, 1 of them with the raised limit, 2 calls of the block read, 3 of them with the raised limit; a transfer that the firmware splits counts one call per piece). Other keys return 0. 0 without the module. See <dk/platform/sdhc_large.h>. Context: any. Since runtime 0.7.0. Needs core/sdhc-large: without it the import binds to a stub that returns 0. */
uint32_t dk_sdhc_large_ctl(dk_sdhc_large *sl, uint32_t key, uint32_t val);

#endif /* DK_GEN_IMPORTS_H */
